BEGIN;
DO $$ DECLARE a uuid;s uuid;s2 uuid;c uuid;doc jsonb;first jsonb;result jsonb;BEGIN
 INSERT INTO public.admin_users(email,password_hash,role,is_active)VALUES('fictional-contact-write@example.test','fictional-proof','admin',true)RETURNING id INTO a;
 INSERT INTO public.admin_sessions(admin_user_id,token_hash)VALUES(a,repeat('1',64))RETURNING id INTO s;
 INSERT INTO public.admin_sessions(admin_user_id,token_hash)VALUES(a,repeat('2',64))RETURNING id INTO s2;
 INSERT INTO public.contact_submissions(name,email,inquiry_type,message,idempotency_key_hash,request_hash)VALUES('Fictional contact write','fictional-contact-write@example.test','general','Fictional private inquiry for atomic write recovery.',repeat('3',64),repeat('4',64))RETURNING id INTO c;
 doc:=jsonb_build_object('status','in_progress');result:=public.inspect_contact_write(a,s,c,1,'status',doc,repeat('5',64),repeat('6',64));IF(result->>'committed')::boolean OR NOT(result->>'canRetry')::boolean OR(SELECT revision FROM public.contact_submissions WHERE id=c)<>1 THEN RAISE EXCEPTION 'Unaccepted contact inspection mutated';END IF;
 first:=public.mutate_contact_write(a,s,c,1,'status',doc,NULL,repeat('5',64),repeat('6',64),NULL);
 result:=public.mutate_contact_write(a,s,c,1,'status',doc,NULL,repeat('5',64),repeat('6',64),NULL);IF result<>first OR(SELECT revision FROM public.contact_submissions WHERE id=c)<>2 THEN RAISE EXCEPTION 'Contact replay duplicated status transition';END IF;
 PERFORM public.mutate_contact_write(a,s,c,2,'status','{"status":"resolved"}',NULL,repeat('7',64),repeat('8',64),NULL);
 result:=public.mutate_contact_write(a,s,c,1,'status',doc,NULL,repeat('5',64),repeat('6',64),NULL);IF result<>first OR(SELECT status FROM public.contact_submissions WHERE id=c)<>'resolved' THEN RAISE EXCEPTION 'Old accepted contact replay overwrote later status';END IF;
 result:=public.inspect_contact_write(a,s2,c,1,'status',doc,repeat('5',64),repeat('6',64));IF(result->>'committed')::boolean OR(result->>'canRetry')::boolean THEN RAISE EXCEPTION 'Contact receipt crossed sessions or stale new retry allowed';END IF;
 BEGIN PERFORM public.inspect_contact_write(a,s,c,1,'status',doc,repeat('5',64),repeat('9',64));RAISE EXCEPTION 'Contact receipt changed body';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'CONFLICT' THEN RAISE;END IF;END;
 doc:=jsonb_build_object('enabled',true,'reason','Fictional independently reviewed retention need','confirmation','HOLD CONTACT');
 BEGIN PERFORM public.mutate_contact_write(a,s,c,3,'hold',doc,NULL,repeat('a',64),repeat('b',64),NULL);RAISE EXCEPTION 'New hold bypassed current password proof';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'VALIDATION_ERROR' THEN RAISE;END IF;END;
 first:=public.mutate_contact_write(a,s,c,3,'hold',doc,'fictional-proof',repeat('a',64),repeat('b',64),NULL);result:=public.mutate_contact_write(a,s,c,3,'hold',doc,NULL,repeat('a',64),repeat('b',64),NULL);
 IF result<>first OR NOT(SELECT retention_hold FROM public.contact_submissions WHERE id=c) OR(SELECT revision FROM public.contact_submissions WHERE id=c)<>4 THEN RAISE EXCEPTION 'Hold accepted replay changed or required retained proof';END IF;
 result:=public.inspect_contact_write(a,s,c,3,'hold',doc,repeat('a',64),repeat('b',64));IF result::text LIKE '%Fictional%' OR result::text LIKE '%@%' OR result::text LIKE '%reason%' OR NOT(result->>'committed')::boolean THEN RAISE EXCEPTION 'Contact inspection leaked private content or lost receipt';END IF;
 UPDATE public.admin_sessions SET revoked_at=now() WHERE id=s;
 BEGIN PERFORM public.inspect_contact_write(a,s,c,3,'hold',doc,repeat('a',64),repeat('b',64));RAISE EXCEPTION 'Revoked contact session read receipt';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'NOT_FOUND' THEN RAISE;END IF;END;
 UPDATE public.admin_sessions SET revoked_at=NULL WHERE id=s;UPDATE public.admin_users SET role='team_member' WHERE id=a;
 BEGIN PERFORM public.inspect_contact_write(a,s,c,3,'hold',doc,repeat('a',64),repeat('c',64));RAISE EXCEPTION 'Current contact authorization checked after hash';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'NOT_FOUND' THEN RAISE;END IF;END;
 UPDATE public.admin_users SET role='admin' WHERE id=a;UPDATE public.idempotency_keys SET expires_at=now()-interval '1 second' WHERE scope='contact-write:'||a||':'||s||':'||c;
 BEGIN PERFORM public.inspect_contact_write(a,s,c,3,'hold',doc,repeat('a',64),repeat('b',64));RAISE EXCEPTION 'Expired contact receipt returned';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'INVALID_STATE' THEN RAISE;END IF;END;
 UPDATE public.contact_submissions SET redacted_at=now() WHERE id=c;
 BEGIN PERFORM public.inspect_contact_write(a,s,c,3,'hold',doc,repeat('a',64),repeat('b',64));RAISE EXCEPTION 'Redacted contact receipt disclosed';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'NOT_FOUND' THEN RAISE;END IF;END;
 IF has_function_privilege('anon','public.inspect_contact_write(uuid,uuid,uuid,integer,text,jsonb,text,text)','EXECUTE') OR has_function_privilege('authenticated','public.mutate_contact_write(uuid,uuid,uuid,integer,text,jsonb,text,text,text,uuid)','EXECUTE') OR NOT has_function_privilege('service_role','public.inspect_contact_write(uuid,uuid,uuid,integer,text,jsonb,text,text)','EXECUTE') THEN RAISE EXCEPTION 'Contact write privileges incorrect';END IF;
END $$;
ROLLBACK;
